const errorMessages={TARGET_REQUIRED:"審査提出前に、上の対象個体を選んでください。",DRAFT_TARGET_CONFLICT:"この下書きは別の個体のものです。対象を戻すか、版の一覧から新しい対象向けの編集用コピーを作ってください。回答はすべて残っています。",TEST_FORMAL_MISMATCH:"アイデンティティと個体の種類が異なります。テストアイデンティティはテスト個体、正式アイデンティティは正式個体にのみ渡せます。同じ種類を選んでください。",DRAFT_REVISION_CONFLICT:"別の画面で下書きが保存されました。未保存内容はここに残っています。コピーしてから最新版を読み、比較してください。",REVIEW_STALE:"提出後に下書きが変更されました。最新候補を提出し、新しい審査提案を開いてください。",PREVIEW_STALE:"設定が変わり、プレビューが古くなりました。更新内容を確認してから承認してください。",PREVIEW_INVALID:"この個体の審査プレビューを利用できません。既存の提案を開き直し、対象を確認してください。",APPROVAL_BLOCKED:"アイデンティティに必須内容の不足や矛盾があります。詳細検証を開き、自己説明を補うか矛盾を直してから提出してください。",COMPILE_FIRST:"回答が変更されました。プレビューで候補を生成してから版を保存・提出してください。",DUPLICATE_INDIVIDUAL:"名前または識別番号は使用済みです。別の名前にするか既存個体を確認してください。",BUILDER_METADATA:"アイデンティティ名を入力してください。詳細識別番号は英小文字、数字、ハイフンのみ使用できます。",INDIVIDUAL_SCHEMA:"100文字以内の個体名を入力してください。詳細識別番号は英小文字、数字、ハイフンのみです。",GLOBAL_STOP:"全体停止中です。Ownerが解除を決めた後、誕生や再開を別途許可してください。",UNBORN:"未誕生です。アイデンティティを承認し、生活設定で初回誕生を準備してください。",WINDOW_CLOSED:"生活時間外です。生活のタイムゾーンと設定を確認するか、次の時間帯を待ってください。",IDENTITY_NOT_APPROVED:"承認済みアイデンティティがありません。保存済みの版を提出し、審査を完了してください。",FORMAL_ADOPTION_FORBIDDEN_IN_ENGINEERING:"隔離工程モードは正式アイデンティティを承認できません。審査待ちのままにし、正式制御画面でOwnerが操作してください。",FORMAL_BIRTH_FORBIDDEN_IN_ENGINEERING:"隔離工程モードでは正式個体を誕生させられません。未誕生のまま保持します。",TASKS_NOT_SETTLED:"作業がまだ終わっていません。個体を停止し、作業なしの表示を待って再試行してください。",PACKAGE_VERSION_CONFLICT:"この版には異なる内容があり、上書きできません。コピーを編集し、新しい版として保存してください。",RECOMPILE_CONFLICT:"回答と手動修正が異なります。差分を見て、修正を保持、新回答を採用、取消から選んでください。",OWNER_AUTH_REQUIRED:"ローカル接続が失効しました。このコピーの制御画面を開く入口で新しいリンクを取得してください。下書きは残っています。",REVIEW_CLOSED:"この提案は処理済みです。最新状態を確認し、変更が必要なら別途提出してください。",PACKAGE_NOT_FOUND:"アイデンティティの版が見つかりません。一覧を更新し、保存済みの版を選んでください。",CONTROL_VERSION_CONFLICT:"個体の状態が更新されました。再読込し、対象を確認してから操作してください。",GLOBAL_VERSION_CONFLICT:"全体の状態が更新されました。再読込して停止状態を確認してください。",PREFLIGHT_BLOCKED:"環境確認が未合格です。環境確認の入口を実行してください。アイデンティティと下書きは引き続き管理できます。",REVIEW_DECISION:"拒否または修正依頼の理由を入力してください。",DRAFT_LIMIT:"下書きの上限です。既存の下書きを続けてください。データは自動削除しません。"};
function friendlyError(e){const code=String(e.message??e).split('：')[0];return errorMessages[code]??(e.name==='TimeoutError'||e.name==='AbortError'?"接続がタイムアウトし、保存できたか確認できません。画面を更新し、下書きまたは審査記録を読み戻して確認してから操作してください。":e instanceof SyntaxError?"ファイルを読み込めません。Kinseedから書き出した完全なアイデンティティパッケージを選び、読み込み直してください。":/^[A-Z][A-Z0-9_:]+$/.test(code)?"データの確認に合格しておらず、この操作の成功は確認できていません。名前・必須項目・選んだパッケージを確認してください。詳細診断は保守担当者に提供できます。":String(e.message??e));}
api=async function(route,b){const r=await fetch('/owner/'+route,{method:b?'POST':'GET',headers:{Authorization:'Bearer '+token,...(b?{'Content-Type':'application/json'}:{})},body:b?JSON.stringify(b):undefined,signal:AbortSignal.timeout(10000)});const x=await r.json();if(!r.ok){const e=Error(x.error);e.conflicts=x.conflicts;throw e;}return x;};
// Never show a successful data object as a wall of JSON in the status banner.
show=v=>{$('message').dataset.error='false';$('message').textContent=typeof v==='string'?v:"操作が完了しました。この画面の保存済み状態を確認してください。";};
bind=function(id,fn){$(id).onclick=async()=>{const urgent=['globalStop','stop'].includes(id);if(busy&&!urgent)return;if(!urgent)busy=true;const button=$(id);button.disabled=true;try{const result=await fn();if(result!==undefined)show(result);await refresh();}catch(e){$('message').dataset.error='true';$('message').textContent="操作が完了していません："+friendlyError(e);const details=el('details');details.append(el('summary',"詳細診断"),el('pre',e.message));$('message').append(details);}finally{if(!urgent)busy=false;button.disabled=false;render();syncReviewButtons();$('submitVersion').disabled=!viewedVersion?.individual_id;}};};
// Rebind preserved operations to consistent progress/error handling (stop remains available).
for(const action of ['resume','pause','stop'])bind(action,()=>command(action));bind('refresh',async()=>{await refresh();return "現在の状態を更新しました。";});
